// Nebesny Archiv - server-side story setup.
//
// Puts the story NPCs into the world next to the spawn point.
//
// The NPC definitions live in config/easy_npc/preset/*.npc.snbt (generated by
// tools/generate-story.mjs). They are imported with Easy NPC's
//   /easy_npc preset import custom <resource location> <x> <y> <z> <uuid>
// The fixed UUIDs matter: importing with a known UUID updates the existing NPC
// instead of spawning a second copy, so this script is safe to run again.
//
// API notes (verified against KubeJS 2101.7.2 / NeoForge 21.1.250):
//   * events are registered by calling them, not by assignment:
//       ServerEvents.tick((event) => { ... })
//   * there is no global "server" in server scripts, it is event.server
//   * event.server.runCommand(cmd) runs a command as the console
//   * event.server.getOverworld().getSharedSpawnPos() gives the world spawn
//   * `const` declared INSIDE a loop body keeps its value from the first
//     iteration in this Rhino build, so `let` is used there on purpose.

const NPCS = [
  {
    name: 'vesta',
    uuid: '3f1c9a52-7d64-4e8b-9a10-5c2f8b6d1e40',
    offset: [3, 0, 2],
  },
  {
    name: 'miya',
    uuid: '6b2d4e77-1c85-4f39-8d6a-2e7c1b9f0d53',
    offset: [-3, 0, 2],
  },
];

const storyState = { placed: false, attempts: 0 };

function placeStoryNpcs(server) {
  const spawn = server.getOverworld().getSharedSpawnPos();

  for (const npc of NPCS) {
    let command =
      `easy_npc preset import custom easy_npc:preset/${npc.name}.npc.snbt ` +
      `${spawn.x + npc.offset[0]} ${spawn.y + npc.offset[1]} ${spawn.z + npc.offset[2]} ` +
      `${npc.uuid}`;
    console.info(`[story] ${command}`);
    server.runCommand(command);
  }

  storyState.placed = true;
  console.info(
    `[story] Story NPCs placed next to the spawn point (${spawn.x}, ${spawn.y}, ${spawn.z})`
  );
}

// The NPCs are placed as soon as the server is up. "loaded" fires once, the
// tick handler is the safety net in case the world was not ready yet.
if (ServerEvents.loaded) {
  ServerEvents.loaded((event) => {
    if (storyState.placed) return;
    try {
      placeStoryNpcs(event.server);
    } catch (error) {
      console.error(`[story] Could not place the story NPCs yet: ${error}`);
    }
  });
}

ServerEvents.tick((event) => {
  if (storyState.placed) return;

  storyState.attempts += 1;
  // Give up after a minute so a broken world does not spam the log.
  if (storyState.attempts > 1200) {
    storyState.placed = true;
    console.error('[story] Gave up placing the story NPCs.');
    return;
  }

  try {
    placeStoryNpcs(event.server);
  } catch (error) {
    if (storyState.attempts === 1) {
      console.error(`[story] Could not place the story NPCs yet: ${error}`);
    }
  }
});
